package strategy

import (
	"context"
	"fmt"
	"log/slog"

	"github.com/entireio/cli/cmd/entire/cli/checkpointpolicy"
	"github.com/entireio/cli/cmd/entire/cli/interactive"
	"github.com/entireio/cli/cmd/entire/cli/logging"
	"github.com/entireio/cli/cmd/entire/cli/paths"
	"github.com/entireio/cli/cmd/entire/cli/versioncheck"
	"github.com/entireio/cli/cmd/entire/cli/versioninfo"
	"github.com/go-git/go-git/v6"
)

func readLocalCheckpointPolicy(ctx context.Context, repo *git.Repository) (checkpointpolicy.Policy, error) {
	state, err := checkpointpolicy.ReadLocal(ctx, repo)
	if err != nil {
		return checkpointpolicy.Policy{}, err
	}
	return state.Policy, nil
}

func checkpointPolicyAllowsGitHook(ctx context.Context, repo *git.Repository) bool {
	policy, err := readLocalCheckpointPolicy(ctx, repo)
	if err != nil {
		warnOrLogCheckpointPolicyReadFailure(ctx, err)
		return false
	}
	if checkpointpolicy.CanSatisfyPolicy(policy) {
		return true
	}
	warnOrLogCheckpointPolicyUpgrade(ctx, policy)
	return false
}

func syncCheckpointPolicyForPrePush(ctx context.Context, repo *git.Repository, ps pushSettings) {
	dir, err := paths.WorktreeRoot(ctx)
	if err != nil {
		logging.Warn(ctx, "checkpoint policy pre-push: failed to resolve worktree root; allowing checkpoint push",
			slog.String("error", err.Error()),
		)
		return
	}
	target := checkpointpolicy.Target{Remote: ps.pushTarget(), Dir: dir}
	state, err := checkpointpolicy.Sync(ctx, repo, target)
	if err != nil {
		warnOrLogCheckpointPolicySyncFailure(ctx, err)
		return
	}
	if state.Source == checkpointpolicy.SourceLocalDiverged {
		warnOrLogCheckpointPolicyDiverged(ctx, state)
		return
	}
}

func warnOrLogCheckpointPolicyReadFailure(ctx context.Context, err error) {
	if interactive.CanPromptInteractively() {
		fmt.Fprintf(stderrWriter, "[entire] Could not read checkpoint policy; skipping Entire checkpoint work: %v\n", err)
		return
	}
	logging.Warn(ctx, "checkpoint policy read failed; skipping checkpoint work",
		slog.String("error", err.Error()),
	)
}

func warnOrLogCheckpointPolicySyncFailure(ctx context.Context, err error) {
	if interactive.CanPromptInteractively() {
		fmt.Fprintf(stderrWriter, "[entire] Could not refresh checkpoint policy: %v\n", err)
		return
	}
	logging.Warn(ctx, "checkpoint policy sync failed",
		slog.String("error", err.Error()),
	)
}

func warnOrLogCheckpointPolicyDiverged(ctx context.Context, state checkpointpolicy.State) {
	if interactive.CanPromptInteractively() {
		fmt.Fprintf(
			stderrWriter,
			"[entire] Could not reconcile checkpoint policy: local checkpoint policy %s diverges from remote %s\n",
			state.Hash,
			state.RemoteHash,
		)
		return
	}
	logging.Warn(ctx, "checkpoint policy diverged; allowing checkpoint push",
		slog.String("local_hash", state.Hash.String()),
		slog.String("remote_hash", state.RemoteHash.String()),
	)
}

func warnIfCheckpointPolicyNeedsUpgrade(ctx context.Context, policy checkpointpolicy.Policy) {
	if checkpointpolicy.CanSatisfyPolicy(policy) {
		return
	}
	warnOrLogCheckpointPolicyUpgrade(ctx, policy)
}

func warnOrLogCheckpointPolicyUpgrade(ctx context.Context, policy checkpointpolicy.Policy) {
	warning := checkpointpolicy.UnsupportedPolicyMessage(policy, versioncheck.UpdateCommandForCurrentBinary(versioninfo.Version))
	if interactive.CanPromptInteractively() {
		fmt.Fprint(stderrWriter, warning)
		return
	}
	logging.Warn(ctx, "checkpoint policy requires newer CLI",
		slog.String("checkpoint_version", policy.CheckpointVersion),
		slog.String("checkpoint_min_version", policy.CheckpointMinVersion),
	)
}

// PushQueuedCheckpointRefs pushes any queued checkpoint refs to the configured
// checkpoint remote, surfacing errors (unlike the fail-soft pre-push path); the
// caller owns the repo. It returns the number of refs pushed and whether
// pushing is disabled in settings — a distinct signal from pushed==0 with
// pushing enabled (an empty queue), so callers can report the two accurately.
// Like the pre-push paths, a checkpoint policy that blocks pushing — or, when
// OPF is enabled, an OPF rewrite that cannot run — errors with the refs left
// queued. Currently used by the checkpoint migration command's opt-in
// "push now".
func PushQueuedCheckpointRefs(ctx context.Context, repo *git.Repository, remote string) (pushed int, pushDisabled bool, err error) {
	ps := resolvePushSettings(ctx, remote)
	if ps.pushDisabled {
		return 0, true, nil
	}
	syncCheckpointPolicyForPrePush(ctx, repo, ps)
	if !checkpointPolicyAllowsGitHook(ctx, repo) {
		return 0, false, errors.New("checkpoint policy does not allow pushing checkpoint refs; refs stay queued")
	}
	if opfErr := opfGateForCheckpointRefs(ctx, repo); opfErr != nil {
		// Names no cause, matching flushCheckpointRefsQueue's retry message
		// below: the gate fails on an unresolvable decision or a failed scan,
		// but also on a ref update that lost a race after a scan that ran
		// fine, so "OPF did not run" would sometimes send the user after the
		// wrong problem. The wrapped error says which it was.
		return 0, false, fmt.Errorf("checkpoint refs stay queued: %w", opfErr)
	}
	pushed, err = flushCheckpointRefsQueue(ctx, repo, ps)
	// Clean up even on a partial/failed flush: a diverged batch can push some
	// refs and still return an error, and the shadow branches for the refs that
	// *did* land must still be cleaned up — parity with the pre-push path, which
	// always runs cleanup after flush regardless of its error.
	cleanupPushedShadowBranches(ctx)
	return pushed, false, err
}

// flushCheckpointRefsQueue drains the push-discovery queue and batch-pushes the
// recorded refs fast-forward-only, recovering a diverged ref by fetch+replay and
// removing from the queue only the refs that land. It returns the number pushed.
//
// Shared by the git-refs pre-push path (which logs and ignores the error to
// never block the user's push) and the migration command's opt-in push (which
// surfaces it). Stale entries — refs no longer present locally — are pruned so
// they don't block the queue forever.
func flushCheckpointRefsQueue(ctx context.Context, repo *git.Repository, ps pushSettings) (int, error) {
	queue, err := checkpoint.PushQueueForRepo(ctx, repo)
	if err != nil {
		return 0, fmt.Errorf("resolve push queue: %w", err)
	}
	queued, err := queue.Drain()
	if err != nil {
		return 0, fmt.Errorf("drain push queue: %w", err)
	}
	if len(queued) == 0 {
		return 0, nil
	}

	pushCtx, pushSpan := perf.Start(ctx, "push_checkpoint_refs")
	defer pushSpan.End()

	existing, stale := partitionLocalRefs(repo, queued)
	if len(stale) > 0 {
		if err := queue.Remove(stale); err != nil {
			logging.Warn(ctx, "git-refs push: prune stale queue entries failed",
				slog.String("error", err.Error()))
		}
	}
	if len(existing) == 0 {
		return 0, nil
	}

	// Resolved here, not by the caller: it spawns `git remote get-url` and its
	// result is unused unless refs are actually pushed, so an ordinary push with
	// an empty queue must not pay for it — nor print the multi-URL warning.
	dest := resolveRefsPushDestination(pushCtx, ps)
	dest.warnIgnoredPushURLs(pushCtx)

	// Progress: pushing many refs over the network can take tens of seconds, so
	// surface it (matching the v1 path's "[entire] Pushing ..." line) instead of
	// leaving the user's git push apparently hung. Written to stderr, which git
	// shows during the pre-push hook.
	fmt.Fprintf(os.Stderr, "[entire] Pushing %d checkpoint ref(s) to %s...", len(existing), dest.display())
	stop := startProgressDots(os.Stderr)

	// Fast path: push all refs in one round-trip (fast-forward-only). If every
	// ref was up to date or fast-forwarded, we're done.
	batchErr := batchPushRefs(pushCtx, dest.target, existing)
	if batchErr == nil {
		stop(" done")
		if removeErr := queue.Remove(existing); removeErr != nil {
			logging.Warn(ctx, "git-refs push: clear pushed refs from queue failed",
				slog.String("error", removeErr.Error()))
		}
		return len(existing), nil
	}
	stop("")

	// Non-interactive SSH auth failures cannot be fixed by per-ref
	// fetch+replay. Surface the same actionable hint as the v1 doPushRef path
	// (issue #1523) instead of only logging to .entire/logs/.
	if nonInteractiveSSHAuthFailure(pushCtx, batchErr) {
		fmt.Fprintf(os.Stderr, "[entire] Warning: couldn't push checkpoint refs: %v\n", batchErr)
		printNonInteractiveSSHAuthHint()
		if dest.checkpointRemote {
			printCheckpointRemoteHint(dest.target)
		}
		return 0, batchErr
	}

	// At least one ref was rejected — typically a non-fast-forward divergence
	// (the same checkpoint re-written on another machine). Retry per ref with
	// fetch+replay recovery, and remove from the queue only the refs that land
	// (a genuine cherry-pick conflict leaves that ref queued for a later push,
	// never force-overwriting the remote).
	// Deliberately names no cause: the batch fails on divergence, but just as
	// often on an unreachable or unauthorized destination. Telling a user with a
	// dead remote that their refs "diverged" — or were "rejected", which equally
	// implies the remote answered — sends them after the wrong problem.
	fmt.Fprintf(os.Stderr, "[entire] Checkpoint ref push failed; retrying %d ref(s) individually...", len(existing))
	stop = startProgressDots(os.Stderr)
	pushed := make([]plumbing.ReferenceName, 0, len(existing))
	var firstErr error
	for _, ref := range existing {
		if err := pushCheckpointRefWithRecovery(pushCtx, dest.target, ref); err != nil {
			logging.Warn(ctx, "git-refs push: checkpoint ref push/sync failed; left queued, not overwritten",
				slog.String("ref", ref.String()), slog.String("error", err.Error()))
			if nonInteractiveSSHAuthFailure(pushCtx, err) {
				printNonInteractiveSSHAuthHint()
			}
			if firstErr == nil {
				firstErr = err
			}
			continue
		}
		pushed = append(pushed, ref)
	}
	stop(fmt.Sprintf(" pushed %d of %d", len(pushed), len(existing)))
	if err := queue.Remove(pushed); err != nil {
		logging.Warn(ctx, "git-refs push: clear pushed refs from queue failed",
			slog.String("error", err.Error()))
	}
	if firstErr != nil {
		return len(pushed), fmt.Errorf("%d of %d checkpoint refs failed to push: %w",
			len(existing)-len(pushed), len(existing), firstErr)
	}
	return len(pushed), nil
}

// cleanupPushedShadowBranches runs post-push shadow-branch cleanup. Failures are
// non-fatal — shadow branches just accumulate until `entire clean` or the next
// successful push.
func cleanupPushedShadowBranches(ctx context.Context) {
	if deleted, cleanupErr := CleanupPushedShadowBranches(ctx); cleanupErr != nil {
		logging.Warn(ctx, "post-push shadow branch cleanup failed",
			slog.String("error", cleanupErr.Error()),
		)
	} else if deleted > 0 {
		logging.Info(ctx, "cleaned up vestigial shadow branches",
			slog.Int("count", deleted),
		)
	}
}

type PushOptions struct {
	Remote    string
	RefSpecs  []string
	ExtraArgs []string // additional flags before remote
	Dir       string
}

// Push runs git push --no-verify --porcelain with token injection.
// GIT_TERMINAL_PROMPT=0 is always set.
func Push(ctx context.Context, remote, refSpec string) (PushResult, error) {
	return PushWithOptions(ctx, PushOptions{
		Remote:   remote,
		RefSpecs: []string{refSpec},
	})
}

// PushWithOptions runs git push --no-verify --porcelain with token injection.
// GIT_TERMINAL_PROMPT=0 is always set.
func PushWithOptions(ctx context.Context, opts PushOptions) (PushResult, error) {
	pushTarget, err := resolvePushCommandTarget(ctx, opts.Remote)
	if err != nil {
		return PushResult{}, fmt.Errorf("resolve push target: %w", err)
	}

	args := []string{"push", "--no-verify", "--porcelain"}
	args = append(args, opts.ExtraArgs...)
	args = append(args, pushTarget)
	args = append(args, opts.RefSpecs...)

	cmd := newCommand(ctx, args...)
	if opts.Dir != "" {
		cmd.Dir = opts.Dir
	}
	disableTerminalPrompt(cmd)
	output, err := cmd.CombinedOutput()
	if err != nil {
		return PushResult{Output: string(output)}, fmt.Errorf("git push: %w", err)
	}
	return PushResult{Output: string(output)}, nil
}

// LsRemoteInDir is like LsRemote but runs in a specific directory.
func LsRemoteInDir(ctx context.Context, dir, remote string, patterns ...string) ([]byte, error) {
	return lsRemote(ctx, dir, remote, patterns...)
}

func lsRemote(ctx context.Context, dir, remote string, patterns ...string) ([]byte, error) {
	args := append([]string{"ls-remote", remote}, patterns...)
	cmd := newCommand(ctx, args...)
	if dir != "" {
		cmd.Dir = dir
	}
	disableTerminalPrompt(cmd)
	out, err := cmd.Output()
	if err != nil {
		return out, fmt.Errorf("git ls-remote: %w", formatGitCommandError(ctx, err, remote))
	}
	return out, nil
}

// formatGitCommandError enriches an exec error from git Output() so callers see
// useful detail: context deadline expiry by name, and git's stderr (auth denied,
// repository not found, DNS) which ExitError otherwise hides behind "exit status N".
// When remote is a URL it may carry credentials that git echoes into stderr;
// those are redacted before the error is returned (same pattern as FetchBlobs).
func formatGitCommandError(ctx context.Context, err error, remote string) error {
	if err == nil {
		return nil
	}
	if errors.Is(ctx.Err(), context.DeadlineExceeded) {
		return fmt.Errorf("deadline exceeded: %w", err)
	}
	var exitErr *exec.ExitError
	if errors.As(err, &exitErr) {
		if stderr := strings.TrimSpace(string(exitErr.Stderr)); stderr != "" {
			if remote != "" {
				stderr = strings.ReplaceAll(stderr, remote, RedactURLOrPath(remote))
			}
			// Collapse whitespace so multi-line git stderr stays one log/attr value.
			stderr = strings.Join(strings.Fields(stderr), " ")
			return fmt.Errorf("%w (%s)", err, stderr)
		}
	}
	return err
}

// IsURL returns true if the target looks like a URL rather than a git remote name.
func IsURL(target string) bool {
	return strings.Contains(target, "://") || strings.Contains(target, "@")
}

// ResolveFetchTarget returns the git fetch target to use. When filtered
// fetches are enabled, configured remotes are resolved to their URL so git does
// not persist promisor settings onto the remote name.
func ResolveFetchTarget(ctx context.Context, target string) (string, error) {
	if IsURL(target) || isLocalPath(target) || !settings.IsFilteredFetchesEnabled(ctx) {
		return target, nil
	}
	url, err := GetRemoteURL(ctx, target)
	if err != nil {
		return "", fmt.Errorf("get remote URL: %w", err)
	}
	return url, nil
}

